# Generators of Groups 
p = 28151
def is_primitive(g, p):
    # For F_p^p, the order of the multiplicative group is p - 1
    # A simple check is to see if generated set has size p - 1,
    # or check powers against divisors of p - 1.
    elem = set()
    curr = 1
    for _ in range(p - 1):
        curr = (curr * g) % p
        elem.add(curr)
    return len(elem) == p - 1


for g in range(2, p):
    if is_primitive(g, p):
        print(f"Smallest generator: {g}")
        break

